// Builds supabase/hosted-setup.sql: every migration + seed + migration history,
// for pasting into the Supabase SQL Editor when the CLI can't reach the project.
// Usage: node scripts/build-hosted-setup.mjs
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const dir = join(root, "supabase", "migrations");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".sql"))
  .sort();

const parts = [
  "-- CatFound hosted setup. Generated by scripts/build-hosted-setup.mjs. Run once in the SQL Editor.",
  "begin;",
];
for (const f of files) parts.push(`\n-- ===== ${f}\n`, readFileSync(join(dir, f), "utf8"));
parts.push("\n-- ===== seed.sql\n", readFileSync(join(root, "supabase", "seed.sql"), "utf8"));
parts.push(`
-- ===== migration history, so \`supabase db push\` won't re-apply these later
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (
  version text primary key, statements text[], name text
);
insert into supabase_migrations.schema_migrations (version, name) values
${files
  .map((f) => {
    const [v, ...n] = f.replace(/\.sql$/, "").split("_");
    return `  ('${v}', '${n.join("_")}')`;
  })
  .join(",\n")}
on conflict (version) do nothing;

commit;

select 'CatFound setup complete: ' || (select count(*) from public.categories) || ' categories, '
  || (select count(*) from public.buildings) || ' buildings' as result;
`);
writeFileSync(join(root, "supabase", "hosted-setup.sql"), parts.join("\n"));
console.log(`wrote supabase/hosted-setup.sql from ${files.length} migrations + seed`);
